jQuery(document).ready(function(e){const c=e("#elementor_clear_cache");c.length&&c.on("click",function(){e.ajax({url:nitropack_elementor.ajax_url,type:"POST",data:{action:"nitropack_elementor_clear_cache",nonce:nitropack_elementor.nonce},dataType:"json",success:function(e){e.success?console.log("[NitroPack] Cache cleared successfully from Elementor Tools"):console.error("[NitroPack] Cache clearing failed:",e.data.message)},error:function(e,c,o){console.error("[NitroPack] AJAX error clearing cache:",o)}})})});